import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_data_line(s: str) -> bool:
        t = s.strip()
        if not t:
            return False
        if t.lower().startswith("source:"):
            return False
        return True

    def parse_records(src: str) -> List[List[str]]:
        reader = csv.reader(io.StringIO(src), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    records = parse_records(text)

    # Remove trailing empty records and preamble/footer lines that are not CSV data.
    cleaned: List[List[str]] = []
    for row in records:
        if len(row) == 0:
            continue
        if len(row) == 1 and not row[0].strip():
            continue
        if len(row) == 1 and row[0].strip().lower().startswith("source:"):
            continue
        cleaned.append([c for c in row])

    if not cleaned:
        return {"columns": [], "rows": []}

    # Detect header rows by looking for initial rows with mostly non-numeric tokens and short widths.
    def token_score(tok: str) -> int:
        t = tok.strip()
        if not t:
            return 0
        if re.fullmatch(r"[\d/:\-]+", t):
            return -1
        if re.search(r"\d", t) and re.search(r"[A-Za-z]", t):
            return 1
        if t.startswith("$"):
            return 1
        return 2

    header_rows = 0
    for i, row in enumerate(cleaned[:5]):
        if len(row) <= 12 and sum(token_score(x) for x in row) >= len(row):
            header_rows += 1
        else:
            break

    if header_rows >= 2:
        header_parts = cleaned[:header_rows]
        data_rows = cleaned[header_rows:]
        maxw = max((len(r) for r in data_rows), default=0)
        cols: List[str] = []
        for c in range(maxw):
            parts = []
            for hr in header_parts:
                if c < len(hr):
                    val = hr[c].strip()
                    if val:
                        parts.append(val)
            cols.append(" ".join(parts).strip())
        # Normalize duplicate/blank column names
        seen = {}
        norm_cols = []
        for idx, col in enumerate(cols):
            name = col if col else f"column_{idx+1}"
            if name in seen:
                seen[name] += 1
                name = f"{name}_{seen[name]}"
            else:
                seen[name] = 1
            norm_cols.append(name)
        rows = []
        for r in data_rows:
            rr = [str(x) for x in r]
            if len(rr) < len(norm_cols):
                rr.extend([""] * (len(norm_cols) - len(rr)))
            elif len(rr) > len(norm_cols):
                rr = rr[:len(norm_cols)]
            rows.append(rr)
        return {"columns": norm_cols, "rows": rows}

    # Fallback: infer first row as header if it looks like one.
    first = cleaned[0]
    rest = cleaned[1:]
    if len(first) > 1 and all(not re.fullmatch(r"[-+]?\d+(\.\d+)?", x.strip()) for x in first):
        cols = [c.strip() if c.strip() else f"column_{i+1}" for i, c in enumerate(first)]
        seen = {}
        norm_cols = []
        for col in cols:
            if col in seen:
                seen[col] += 1
                col = f"{col}_{seen[col]}"
            else:
                seen[col] = 1
            norm_cols.append(col)
        rows = []
        for r in rest:
            rr = [str(x) for x in r]
            if len(rr) < len(norm_cols):
                rr.extend([""] * (len(norm_cols) - len(rr)))
            elif len(rr) > len(norm_cols):
                rr = rr[:len(norm_cols)]
            rows.append(rr)
        return {"columns": norm_cols, "rows": rows}

    maxw = max((len(r) for r in cleaned), default=0)
    cols = [f"column_{i+1}" for i in range(maxw)]
    rows = []
    for r in cleaned:
        rr = [str(x) for x in r]
        if len(rr) < maxw:
            rr.extend([""] * (maxw - len(rr)))
        elif len(rr) > maxw:
            rr = rr[:maxw]
        rows.append(rr)
    return {"columns": cols, "rows": rows}
